raw.query:
SELECT i.achieved_p99_ms, i.is_violation, i.bound_ms FROM v_infraction i WHERE i.is_current = TRUE AND i.run_id = 'ctmatrix:forecast_steady24h_p50_rho15';
-- and:
SELECT readiness, COUNT(*) FILTER (WHERE all_feasible) AS feasible, COUNT(*) AS total FROM v_closedloop_frontier WHERE quantile = 'p50' AND rho = 15 AND readiness = 'strict' GROUP BY readiness
